<template>
  <sravx-page-back root-only />

  <view class="page"><view class="head"><image :src="avatar" mode="aspectFill"/><text>个人资料</text></view><view class="form"><view class="field"><text>用户名</text><input v-model="form.username" maxlength="20" placeholder="请输入用户名"/></view><view class="field"><text>性别</text><view class="gender"><view v-for="item in genders" :key="item" :class="{ active: form.gender === item }" @tap="form.gender=item">{{ item }}</view></view></view><view class="field"><text>生日</text><picker mode="date" start="1940-01-01" :end="birthdayEnd" :value="form.birthday" @change="form.birthday=$event.detail.value"><view :class="form.birthday ? 'value' : 'placeholder'">{{ form.birthday || '请选择出生日期' }}</view></picker></view><view class="field"><text>职业</text><picker :range="occupations" :value="occupationIndex" @change="setOccupation"><view :class="form.occupation ? 'value' : 'placeholder'">{{ form.occupation || '请选择职业' }}</view></picker></view></view><view class="save-area"><button class="save" :class="{ disabled: saving }" @tap="save">{{ saving ? '保存中' : '保存' }}</button></view></view>
</template>
<script>
import SravxPageBack from '../../components/sravx-page-back/sravx-page-back.vue'

import api from '../../common/api.js'
import auth from '../../common/auth.js'
const dateOnly = value => { const match = String(value || '').match(/^\d{4}-\d{2}-\d{2}/); return match ? match[0] : '' }
export default {components:{SravxPageBack}, data() { const now = new Date(); return { avatar: '/static/navigation/sravx-mark.png', form: { username: '', gender: '', birthday: '', occupation: '' }, genders: ['男', '女'], occupations: ['宠物美容师A级', '宠物美容师B级', '宠物美容师C级', '宠物美容学徒', '其他'], occupationIndex: -1, birthdayEnd: `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`, saving: false } }, onLoad() { const user = auth.user(); if (!user || !user.phone) return uni.redirectTo({ url: '/pages/register/index' }); this.fill(user); this.load() }, methods: { fill(info) { const occupation = info.occupation || ''; this.avatar = info.avatar || '/static/navigation/sravx-mark.png'; this.form = { username: info.username || info.nickname || '', gender: info.gender === 'unknown' ? '' : info.gender || '', birthday: dateOnly(info.birthday), occupation }; this.occupationIndex = this.occupations.indexOf(occupation) }, async load() { try { const info = await api.getUserInfo(); if (info) this.fill(info) } catch (error) {} }, setOccupation(event) { this.occupationIndex = Number(event.detail.value); this.form.occupation = this.occupations[this.occupationIndex] || '' }, save() { const username = this.form.username.trim(); if (!username) return uni.showToast({ title: '请输入用户名', icon: 'none' }); if (this.saving) return; uni.showModal({ title: '确认保存', content: '个人资料每月仅可修改一次，保存后本月将无法再次修改，确定保存吗？', confirmText: '确定保存', cancelText: '再想想', success: async ({ confirm }) => { if (!confirm) return; this.saving = true; try { const profile = { username, gender: this.form.gender || '', birthday: dateOnly(this.form.birthday), occupation: this.form.occupation || '' }; await api.updateUserInfo({ ...profile, enforceMonthlyLimit: true }); auth.save({ ...(auth.user() || {}), ...profile, nickname: username, avatar: this.avatar }); uni.showToast({ title: '保存成功', icon: 'success' }); setTimeout(() => uni.navigateBack(), 700) } catch (error) { const message = error.message || '保存失败'; if (message.includes('本月已修改过资料')) uni.showModal({ title: '暂不能修改', content: message, showCancel: false }); else uni.showToast({ title: message, icon: 'none' }) } finally { this.saving = false } } }) } } }
</script>
<style>
.page{min-height:100vh;background:#F4F6F8}.head{display:flex;align-items:center;gap:12px;padding:22px 24px 17px;background:#fff;font-size:19px;font-weight:700}.head image{width:48px;height:48px;border-radius:50%;background:#eee}.form{margin-top:12px;padding:0 20px;background:#fff}.field{display:flex;align-items:center;justify-content:space-between;min-height:53px;border-bottom:1px solid #eee;font-size:15px}.field>text{width:70px;font-weight:500}.field input,.field picker{flex:1;text-align:right;font-size:15px}.field picker{padding:17px 0}.placeholder{color:#c7c7cc}.value{color:#0B0D10}.gender{display:flex;gap:8px}.gender view{min-width:50px;padding:7px 9px;border:1px solid #e5e5ea;border-radius:6px;color:#636366;text-align:center;font-size:14px}.gender view.active{border-color:#0B0D10;background:#0B0D10;color:#fff}.save-area{padding:28px 20px}.save{border-radius:8px;background:#0B0D10;color:#fff;font-size:16px;line-height:46px}.save::after{border:0}.save.disabled{opacity:.6}
</style>
